@GameTestHolder("tncarcana") @PrefixGameTestTemplate(false)
public final class ArcanaGameTests {
 private static RouteNodeEntity node(GameTestHelper h,BlockPos relative,RouteKind kind,UUID owner){var at=h.absolutePos(relative);h.getLevel().setBlock(at,RouteContent.NODES.get(kind.id).get().defaultBlockState(),3);var n=(RouteNodeEntity)h.getLevel().getBlockEntity(at);n.owner=owner;return n;}
 private static AlchemyEntity pot(GameTestHelper h,Elixir e){var at=h.absolutePos(new BlockPos(2,2,2));h.getLevel().setBlock(at,net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),3);h.getLevel().setBlock(at,AlchemyContent.CAULDRON.defaultBlockState(),3);var n=(AlchemyEntity)h.getLevel().getBlockEntity(at);n.addWater();for(int i=0;i<3;i++)n.insert(new ItemStack(ArcanaContent.item(e.ingredients.get(i)),2));n.insert(new ItemStack(AlchemyContent.FUEL));return n;}
 @GameTest(template="building_test_empty",timeoutTicks=40) public static void basicPoolsCannotOverload(GameTestHelper h){var n=node(h,new BlockPos(2,2,2),RouteKind.POOL,UUID.randomUUID());n.inRate=10000;ArcanaDevices.tick(h.getLevel(),n);h.assertTrue(!n.getPersistentData().contains("overload_level"),"newbie pool has no overload state");h.succeed();}
 @GameTest(template="building_test_empty",timeoutTicks=40) public static void towerRequiresActualTwentyFourBricks(GameTestHelper h){var n=node(h,new BlockPos(3,2,3),RouteKind.ABYSS_TOWER,UUID.randomUUID());h.assertTrue(n.receive(1000)==0,"unformed tower rejects input");for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)for(int y=0;y<3;y++)if(x!=0||z!=0)h.getLevel().setBlock(n.getBlockPos().offset(x,y,z),ArcanaContent.TOWER_BRICK.defaultBlockState(),3);h.assertTrue(ArcanaDevices.formed(h.getLevel(),n.getBlockPos())&&n.receive(1000)==1000,"all twenty four bricks unlock actual capacity");n.inRate=2000;ArcanaDevices.tick(h.getLevel(),n);h.assertTrue(n.getPersistentData().getDouble("overload_level")>0,"actual high intake increases pressure");h.succeed();}
 @GameTest(template="building_test_empty",timeoutTicks=40) public static void overloadBonusCannotCrossForeignOwnership(GameTestHelper h){UUID owner=UUID.randomUUID();var tower=node(h,new BlockPos(2,2,2),RouteKind.ABYSS_TOWER,owner);var own=node(h,new BlockPos(3,2,2),RouteKind.SAWMILL,owner);var foreign=node(h,new BlockPos(2,2,3),RouteKind.SAWMILL,UUID.randomUUID());ArcanaDevices.boostConnected(h.getLevel(),tower,1000);h.assertTrue(own.getPersistentData().getLong("OverloadBoostUntil")==1000&&!foreign.getPersistentData().contains("OverloadBoostUntil"),"only connected same-owner machines receive bonus");h.succeed();}
 @GameTest(template="building_test_empty",timeoutTicks=40) public static void elementalNetworkCreditsAreConserved(GameTestHelper h){UUID id=UUID.randomUUID();var a=node(h,new BlockPos(2,2,2),RouteKind.LUNAR,id);var b=node(h,new BlockPos(3,2,2),RouteKind.NURTURE,id);a.receive(500);ArcanaEnergy.credit(a,"lunar",500);b.receive(80);ArcanaEnergy.transfer(a,b,80);a.extract(80);h.assertTrue(a.mana==420&&b.mana==80&&ArcanaEnergy.amount(a,"lunar")==420&&ArcanaEnergy.amount(b,"lunar")==80,"real and typed balances move together");h.assertTrue(ArcanaEnergy.spend(b,"lunar",50)&&b.mana==30&&ArcanaEnergy.amount(b,"lunar")==30&&!ArcanaEnergy.spend(b,"lunar",31),"typed spending cannot duplicate or overdraw");h.succeed();}
 @GameTest(template="building_test_empty",timeoutTicks=40) public static void coldPotCannotBeSealedWithoutFireMagic(GameTestHelper h){var n=pot(h,Elixir.SPRING);n.temperature=500;n.vortex_sync=100;n.perfectRemaining=30;h.assertTrue(!n.ignite(false)&&!n.seal(null)&&n.water==3,"temperature spoof alone cannot bypass actual spell ignition");h.succeed();}
 @GameTest(template="building_test_empty",timeoutTicks=40) public static void goldenFrameSurvivesSaveAndConsumesOnce(GameTestHelper h){var n=pot(h,Elixir.SPRING);n.ignite(true);n.temperature=500;n.stirs=3;n.job="spring";n.progress=Elixir.SPRING.ticks-1;AlchemyEntity.tick(h.getLevel(),n.getBlockPos(),n.getBlockState(),n);h.assertTrue(n.perfectRemaining==29&&n.vortex_sync==100,"exact 1.5 second frame begins");var saved=n.saveWithoutMetadata();var copy=new AlchemyEntity(n.getBlockPos(),n.getBlockState());copy.load(saved);copy.setLevel(h.getLevel());h.assertTrue(copy.hasIgnited&&copy.perfectRemaining==29&&copy.seal(null)&&copy.readyQuality==2,"restart retains ignition, timing and master result");h.assertTrue(!copy.seal(null)&&copy.water==2&&copy.inventory.getItem(0).getCount()==0,"exact one herb per input and one water");h.succeed();}
 @GameTest(template="building_test_empty",timeoutTicks=40) public static void sustainedOverheatCreatesWasteAndConsumesOneBatch(GameTestHelper h){var n=pot(h,Elixir.SPRING);n.ignite(true);n.temperature=850;n.burn=1000;for(int i=0;i<100;i++)AlchemyEntity.tick(h.getLevel(),n.getBlockPos(),n.getBlockState(),n);h.assertTrue(n.readyQuality==3&&n.ready.equals("spring")&&n.water==2&&n.fire==0,"five hot seconds explode into actual waste, no terrain explosion");h.succeed();}
 @GameTest(template="building_test_empty",timeoutTicks=40) public static void waterSpellCoolingRespectsOwnership(GameTestHelper h){var n=pot(h,Elixir.SPRING);var p=AdventureGameTests.player(h);var other=AdventureGameTests.player(h);n.owner=p.getUUID();n.temperature=750;AlchemyEntity.coolNear(h.getLevel(),n.getBlockPos(),other);h.assertTrue(n.temperature==750,"foreign caster cannot alter owned potion");AlchemyEntity.coolNear(h.getLevel(),n.getBlockPos(),p);h.assertTrue(n.temperature==530,"owner's real water collision hook cools exactly 220");h.succeed();}
 @GameTest(template="building_test_empty",timeoutTicks=40) public static void everyFarmPotionHasARealCauldronRecipe(GameTestHelper h){for(var e:Elixir.values()){var n=pot(h,e);h.assertTrue(n.recipe()==e&&AlchemyContent.POTIONS.get(e)==ArcanaContent.item(e.outputId()),"recipe and actual registered result "+e.id);for(String id:e.ingredients)h.assertTrue(ArcanaContent.item(id)!=null&&ArcanaContent.item(id)!=Items.AIR,"real material "+id);}h.succeed();}
 @GameTest(template="building_test_empty",timeoutTicks=40) public static void lastFarmPotionReturnsItsBottle(GameTestHelper h){var p=AdventureGameTests.player(h);var s=new ItemStack(ArcanaContent.item("overdraft_elixir"));ArcanaItem.consume(p,s);h.assertTrue(s.isEmpty()&&p.getInventory().countItem(Items.GLASS_BOTTLE)==1,"last bottle returns one container");h.succeed();}
 @GameTest(template="building_test_empty",timeoutTicks=40) public static void giantFruitKeepsItsOriginalPlantProduct(GameTestHelper h){var p=AdventureGameTests.player(h);var at=h.absolutePos(new BlockPos(2,2,2));h.getLevel().setBlock(at.below(),RouteContent.SOIL.get().defaultBlockState(),3);h.getLevel().setBlock(at,RouteContent.PLANTS.get(NewPlantKind.PRISM.id).get().defaultBlockState().setValue(RoutePlantBlock.AGE,3),3);var plant=(RoutePlantEntity)h.getLevel().getBlockEntity(at);plant.owner=p.getUUID();plant.growth=18000;var potion=new ItemStack(ArcanaContent.item("gigantism_elixir"));h.assertTrue(ArcanaEcology.applyPlant(p,at,"gigantism_elixir",potion)&&potion.isEmpty(),"real giant potion consumed");h.assertTrue(ArcanaEcology.giantHarvest(p,plant),"giant fruit collected");var fruit=p.getInventory().items.stream().filter(s->s.is(ArcanaContent.item("giant_mana_fruit"))).findFirst().orElseThrow();h.assertTrue(ArcanaEcology.giantProduct(fruit)==RouteContent.item(NewPlantKind.PRISM.product)&&plant.growth==6000,"saw output maps to actual original plant, root resets");h.succeed();}
 @GameTest(template="building_test_empty",timeoutTicks=40) public static void simpleSymbiosisOnlyNeedsNearbyCompatibleOwnedAnimal(GameTestHelper h){var p=AdventureGameTests.player(h);var at=h.absolutePos(new BlockPos(2,2,2));h.getLevel().setBlock(at.below(),Blocks.DIRT.defaultBlockState(),3);h.getLevel().setBlock(at,BotanicalContent.BLOCKS.get("honey_cluster").defaultBlockState(),3);var plant=(BotanicalPlantEntity)h.getLevel().getBlockEntity(at);plant.owner=p.getUUID();plant.growth=plant.species().firstTicks;var animal=PastureRegistry.TYPES.get("mirrorwing_moth").create(h.getLevel());var tag=new CompoundTag();animal.addAdditionalSaveData(tag);tag.putUUID("PastureOwner",p.getUUID());animal.readAdditionalSaveData(tag);animal.setPos(at.getX()+2,at.getY(),at.getZ());animal.setNoAi(true);h.getLevel().addFreshEntity(animal);h.runAfterDelay(20-h.getLevel().getGameTime()%20,()->{ArcanaEcology.tickPlant(h.getLevel(),at,plant);h.assertTrue(ArcanaEcology.factor(h.getLevel(),plant)==1.2&&animal.getPersistentData().getLong("ResonanceUntil")>h.getLevel().getGameTime(),"proximity alone grants exactly twenty percent, no ritual or item");animal.discard();h.succeed();});}
 @GameTest(template="building_test_empty",timeoutTicks=40) public static void toxicityPersistsAndSpaUnlocksClearChannels(GameTestHelper h){var p=AdventureGameTests.player(h);ArcanaPhysiology.drink(p,RitualRules.Quality.CLOUDY);ArcanaPhysiology.drink(p,RitualRules.Quality.STANDARD);h.assertTrue(ArcanaPhysiology.toxicity(p)==35,"real 25+10 ingestion");ArcanaPhysiology.toxic(p,100);h.assertTrue(!ArcanaPhysiology.permitDrink(p),"critical toxicity rejects new potion");ArcanaPhysiology.detox(p,100);h.assertTrue(ArcanaPhysiology.toxicity(p)==0&&ArcanaPhysiology.clearChannels(p),"detox reaches zero and grants actual day-long recovery state");h.succeed();}
 @GameTest(template="building_test_empty",timeoutTicks=40) public static void foodPlateRequiresFiveTastesAndNeutralSeparation(GameTestHelper h){var p=AdventureGameTests.player(h);var n=node(h,new BlockPos(2,2,2),RouteKind.MEAL_PLATE,p.getUUID());Item[] foods={BotanicalContent.PRODUCTS.get("hearth_pepper_fruit"),ArcanaContent.item("slime_pudding"),Items.COOKED_COD,Items.COOKED_CHICKEN,Items.BAKED_POTATO,ArcanaContent.item("moon_honey_cake"),Items.BREAD,Items.BREAD,Items.BREAD};for(int i=0;i<9;i++)n.inventory.setItem(i,new ItemStack(foods[i]));h.assertTrue(!ArcanaMeals.conflict(n)&&ArcanaMeals.active(n),"neutral middle food separates fire and water into a real five-taste array");p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);ArcanaMeals.interact(p,n,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(n.getBlockPos()),Direction.UP,n.getBlockPos(),false));h.assertTrue(n.inventory.isEmpty()&&ArcanaPhysiology.data(p).getLong("MealSunUntil")>ArcanaPhysiology.now(p),"actual nine food items consumed and mobile sun granted");var magic=com.tnc.tnc.magic.MagicStone.getOrNull(p);for(int i=0;i<50;i++)h.assertTrue(magic.spendMana(magic.getMaxMana()),"meal sun supports consecutive real casts without per-second refill gaps");h.succeed();}
 @GameTest(template="building_test_empty",timeoutTicks=40) public static void fullInventorySpiritContractNeverChargesHealth(GameTestHelper h){var p=AdventureGameTests.player(h);var spirit=ArcanaContent.SPIRIT.create(h.getLevel());spirit.owner=p.getUUID();spirit.setPos(p.getX(),p.getY(),p.getZ());h.getLevel().addFreshEntity(spirit);com.tnc.tnc.mana.sight.ManaSightServer.subscribe(p,true);ArcanaPhysiology.data(p).putDouble("vision_sanity",90);for(int i=0;i<36;i++)p.getInventory().setItem(i,new ItemStack(Items.STONE,64));float hp=p.getHealth();ArcanaSpirits.trade(p,spirit.getId(),0);h.assertTrue(p.getHealth()==hp,"full inventory cannot pay life for missing reward");p.getInventory().setItem(0,ItemStack.EMPTY);ArcanaSpirits.trade(p,spirit.getId(),0);h.assertTrue(p.getHealth()<hp&&p.getInventory().countItem(ArcanaContent.item("dimensional_mana_prism"))==1,"valid pact delivers actual prism once");float after=p.getHealth();ArcanaSpirits.trade(p,spirit.getId(),0);h.assertTrue(p.getHealth()==after,"daily cooldown cannot charge twice");spirit.discard();h.succeed();}
 @GameTest(template="building_test_empty",timeoutTicks=40) public static void capturedMonsterTokenCannotDeployTwoCopies(GameTestHelper h){var p=AdventureGameTests.player(h);var mob=net.minecraft.world.entity.EntityType.ZOMBIE.create(h.getLevel());mob.setPos(p.getX(),p.getY(),p.getZ());mob.setHealth(4);h.getLevel().addFreshEntity(mob);var potion=new ItemStack(ArcanaContent.item("capture_shrink_elixir"));h.assertTrue(ArcanaEcology.applyAnimal(p,mob,"capture_shrink_elixir",potion),"low-health monster gets ten-second capture mark");var empty=new ItemStack(RouteContent.item("ecology_restraint_cage"));h.assertTrue(ArcanaCages.capture(p,mob,empty)&&!mob.isAlive(),"actual monster serialized and removed");var packed=p.getInventory().items.stream().filter(s->s.is(RouteContent.item("ecology_restraint_cage"))).findFirst().orElseThrow();var a=node(h,new BlockPos(2,2,2),RouteKind.RESTRAINT,p.getUUID());var b=node(h,new BlockPos(4,2,2),RouteKind.RESTRAINT,p.getUUID());ArcanaCages.placed(p,a,packed);ArcanaCages.placed(p,b,packed.copy());a.mana=100;b.mana=100;ArcanaCages.tick(h.getLevel(),a);ArcanaCages.tick(h.getLevel(),b);h.assertTrue(a.getPersistentData().hasUUID("Captive")&&!b.getPersistentData().hasUUID("Captive"),"shared server ledger deploys exactly one entity even for copied item NBT");h.succeed();}
 @GameTest(template="building_test_empty",timeoutTicks=40) public static void skyPathRequiresOwnedLoadedUnobstructedRings(GameTestHelper h){var id=UUID.randomUUID();var a=node(h,new BlockPos(1,3,1),RouteKind.SKY_LAUNCHER,id);var b=node(h,new BlockPos(5,3,1),RouteKind.SKY_RELAY,id);a.getPersistentData().putLong("SkyTarget",b.getBlockPos().asLong());h.assertTrue(ArcanaHighway.path(h.getLevel(),a).size()==2,"real ring link resolves");a.mana=100;ArcanaHighway.tick(h.getLevel(),a);h.assertTrue(a.mana==92&&a.getPersistentData().getLongArray("SkyPath").length==2,"real path spends eight mana per segment");h.getLevel().setBlock(h.absolutePos(new BlockPos(3,3,1)),Blocks.STONE.defaultBlockState(),3);h.assertTrue(ArcanaHighway.path(h.getLevel(),a).size()==1,"solid wall prevents travel link");h.succeed();}
 @GameTest(template="building_test_empty",timeoutTicks=40) public static void advancedAssetsAndRecipesExist(GameTestHelper h){for(var k:RouteKind.values())if(k.ordinal()>=RouteKind.ABYSS_TOWER.ordinal()){h.assertTrue(RouteContent.item(k.id)!=Items.AIR,"registered actual device "+k.id);h.assertTrue(h.getLevel().getServer().getResourceManager().getResource(net.minecraft.resources.ResourceLocation.parse("tnc:recipes/arcana/"+k.id+".json")).isPresent()||k==RouteKind.DIMENSION_PRISM,"obtainable recipe or contract "+k.id);}h.succeed();}
 @GameTest(template="building_test_empty",timeoutTicks=40) public static void towerShellActuallyReceivesFromMultipleFaces(GameTestHelper h){UUID id=UUID.randomUUID();var n=node(h,new BlockPos(3,2,3),RouteKind.ABYSS_TOWER,id);for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)for(int y=0;y<3;y++)if(x!=0||z!=0)h.getLevel().setBlock(n.getBlockPos().offset(x,y,z),ArcanaContent.TOWER_BRICK.defaultBlockState(),3);var a=node(h,new BlockPos(5,2,3),RouteKind.SOLAR,id);var b=node(h,new BlockPos(1,2,3),RouteKind.LUNAR,id);a.mana=700;b.mana=700;RouteNetwork.tickNetwork(h.getLevel());h.assertTrue(n.mana==1024&&a.mana==188&&b.mana==188,"two real shell faces accept source-limited transfers, no bottom-only wiring");h.succeed();}
 @GameTest(template="building_test_empty",timeoutTicks=40) public static void brokenCageCannotRebindAnotherCagesLiveMob(GameTestHelper h){UUID owner=UUID.randomUUID();var a=node(h,new BlockPos(1,2,1),RouteKind.RESTRAINT,owner);var b=node(h,new BlockPos(4,2,1),RouteKind.RESTRAINT,owner);var mob=net.minecraft.world.entity.EntityType.BLAZE.create(h.getLevel());mob.setPos(b.getBlockPos().getX()+.5,b.getBlockPos().getY(),b.getBlockPos().getZ()+.5);mob.getPersistentData().putUUID("CageOwner",owner);mob.getPersistentData().putLong("CagePos",b.getBlockPos().asLong());h.getLevel().addFreshEntity(mob);a.getPersistentData().putUUID("Captive",mob.getUUID());a.mana=100;ArcanaCages.tick(h.getLevel(),a);h.assertTrue(!a.getPersistentData().hasUUID("Captive")&&a.mana==100&&ArcanaCages.bound(b,mob),"stale A cannot maintain or farm B's real captive");mob.discard();h.succeed();}
 @GameTest(template="building_test_empty",timeoutTicks=40) public static void deadDisasterReceiptClearsAnUnloadedTowerUuid(GameTestHelper h){var n=node(h,new BlockPos(2,2,2),RouteKind.ABYSS_TOWER,UUID.randomUUID());UUID dead=UUID.randomUUID();n.getPersistentData().putUUID("Devourer",dead);ArcanaDisasters.get(h.getLevel()).mark(dead);ArcanaDevices.tick(h.getLevel(),n);h.assertTrue(!n.getPersistentData().hasUUID("Devourer")&&ArcanaDisasters.get(h.getLevel()).save(new CompoundTag()).getCompound("Killed").getBoolean(dead.toString()),"persistent receipt clears moved tower even after entity removal");h.succeed();}
 @GameTest(template="building_test_empty",timeoutTicks=40) public static void completingRemoteShellRefreshesAlreadyPlacedFiber(GameTestHelper h){UUID id=UUID.randomUUID();var n=node(h,new BlockPos(3,2,3),RouteKind.ABYSS_TOWER,id);for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)for(int y=0;y<3;y++)if(x!=0||z!=0)h.getLevel().setBlock(n.getBlockPos().offset(x,y,z),ArcanaContent.TOWER_BRICK.defaultBlockState(),3);var last=n.getBlockPos().offset(-1,2,-1);h.getLevel().setBlock(last,Blocks.AIR.defaultBlockState(),3);var wire=node(h,new BlockPos(5,2,3),RouteKind.CRYSTAL_WIRE,id);var source=node(h,new BlockPos(6,2,3),RouteKind.SOLAR,id);source.mana=500;h.getLevel().setBlock(last,ArcanaContent.TOWER_BRICK.defaultBlockState(),3);ArcanaDevices.tick(h.getLevel(),n);h.assertTrue(h.getLevel().getBlockState(wire.getBlockPos()).getValue(RouteWireBlock.ARMS.get(Direction.WEST)),"remote final brick refreshes existing tower fiber arm");RouteNetwork.tickNetwork(h.getLevel());h.assertTrue(n.mana==128,"completed shell receives via actual two-ended fiber at its shared 128M rate");h.succeed();}
 @GameTest(template="building_test_empty",timeoutTicks=40) public static void thornArmorDoesNotAttackSpiritsOrCaptiveWorkers(GameTestHelper h){
  var p=AdventureGameTests.player(h);var at=h.absolutePos(new BlockPos(2,2,2));p.setPos(at.getX()+.5,at.getY(),at.getZ()+.5);var armor=new ItemStack(ArcanaContent.item("thorn_tyrant_vine"));armor.getOrCreateTag().putUUID("RootedOwner",p.getUUID());armor.getOrCreateTag().putInt("PlantMana",100);p.setItemSlot(net.minecraft.world.entity.EquipmentSlot.CHEST,armor);
  var spirit=ArcanaContent.SPIRIT.create(h.getLevel());spirit.owner=p.getUUID();spirit.setPos(p.getX(),p.getY(),p.getZ()+1);h.getLevel().addFreshEntity(spirit);
  var worker=net.minecraft.world.entity.EntityType.ZOMBIE.create(h.getLevel());worker.setNoAi(true);worker.setPos(p.getX()-1,p.getY(),p.getZ());worker.getPersistentData().putUUID("CageOwner",p.getUUID());h.getLevel().addFreshEntity(worker);
  var enemy=net.minecraft.world.entity.EntityType.ZOMBIE.create(h.getLevel());enemy.setNoAi(true);enemy.setPos(p.getX()+1,p.getY(),p.getZ());h.getLevel().addFreshEntity(enemy);
  var mana=com.tnc.tnc.magic.MagicStone.getOrNull(p);mana.setMaxMana(100);mana.setMana(100);double beforeY=p.getY();ArcanaEquipment.tick(p);h.assertTrue(enemy.getHealth()<enemy.getMaxHealth(),"real hostile is still struck");h.assertTrue(worker.getHealth()==worker.getMaxHealth()&&spirit.getHealth()==spirit.getMaxHealth(),"neutral spirit and contained worker are not attacked");h.assertTrue(p.getY()==beforeY&&mana.getMana()==99,"automatic armor spends its one mana and never invokes divine punishment");spirit.discard();worker.discard();enemy.discard();h.succeed();
 }
}
